  for all using (false);
create policy "Users cannot modify team_members" on public.team_members
  for all using (false);

-- R8: Anonymous visitors cannot see or change anything
-- The policies above already restrict to authenticated users via auth.uid().
-- Explicitly deny anon role if needed (Supabase default handles this, but explicit for clarity):
revoke all on public.teams from anon;
revoke all on public.team_members from anon;
revoke all on public.documents from anon;

