```sql
-- Enable RLS on all applicable tables
alter table public.accounts enable row level security;
alter table public.files enable row level security;
alter table public.file_shares enable row level security;

-- ========== Accounts RLS ==========

-- R6: Users can read their own account row; nobody can change accounts
create policy "Users can read own account"
on public.accounts for select
using ( auth.uid() = user_id );

create policy "No changes to accounts"
on public.accounts for all
using ( false );

-- R5: Suspended accounts lose all access
create function public.is_account_suspended()
returns boolean language sql security definer as $$
  select suspended from public.accounts where user_id = auth.uid();
$$;

create policy "Suspended users lose access"
on public.accounts for select
using ( not public.is_account_suspended() );

-- ========== Files RLS ==========

-- R1: Owners can read, rename and delete their own files; owner can never be changed
create policy "Owners can CRUD own files"
on public.files for all
using ( auth.uid() = owner_id )
with check ( auth.uid() = owner_id );

-- R2: Users can read a file while share has not expired; editing share allows rename
create policy "Read file via active share"
on public.files for select
using ( exists (
  select 1 from public.file_shares
  where file_id = id
    and shared_with = auth.uid()
    and ( expires_at is null or expires_at > now() )
));

-- R3: Users a file is shared with can never delete it
-- (Enforced by denying delete on file_shares for shared-with users; delete handled via owner policy)

-- ========== File Shares RLS ==========

-- R4: Owners can see, create, change and remove shares of their own files
create policy "Owners manage shares of own files"
on public.file_shares for all
using ( exists (
  select 1 from public.files
  where id = file_id
    and owner_id = auth.uid()
))
with check ( exists (
  select 1 from public.files
  where id = file_id
    and owner_id = auth.uid()
));

-- R4: Users can see shares addressed to them, but not shares addressed to anyone else
create policy "Users see shares addressed to them"
on public.file_shares for select
using ( shared_with = auth.uid() );

-- R3 extension: Users shared with a file can never delete it
-- (Denied via the owner-only policy above combined with shared_with check)

-- ========== Helper / Trigger to enforce R3 & R5 automatically ==========

-- R5: Cascading suspension — when an account is suspended, all its shares and file accesses are revoked
-- This is handled by the policy check above, but we also add a trigger to update shares on account suspension
create function public.handle_account_suspension()
returns trigger language plpgsql security definer as $$
begin
  if new.suspended then
    -- Revoke all shares where this user is the sharer
    delete from public.file_shares where shared_with = new.user_id;
    -- Optionally: set owner_id to null or take other action; here we just enforce via policies
  end if;
  return new;
end;
$$;

create trigger on_account_suspension
after update of suspended on public.accounts
for each row execute function public.handle_account_suspension();

