```sql
-- Enable RLS on tables
alter table public.invoices enable row level security;
alter table public.finance_staff enable row level security;

-- RLS Policies for invoices

-- R1: Users can read their own invoices; finance staff can read all invoices
create policy "Users can read own invoices" on public.invoices
  for select using (created_by = auth.uid());

create policy "Finance staff can read all invoices" on public.invoices
  for select using (exists (select 1 from public.finance_staff where user_id = auth.uid()));

-- R2: Users can create invoices only as themselves, only as drafts
create policy "Users can create draft invoices only" on public.invoices
  for insert with check (created_by = auth.uid() and status = 'draft');

-- R3: Creator of a draft can change customer/amount; status draft→sent allowed.
-- Once not draft, nobody can change customer or amount.
create or replace function public.validate_invoice_update()
returns trigger as $$
begin
  -- Rule 6: Nobody can change who created an invoice
  if new.created_by != old.created_by then
    raise exception 'Cannot change created_by';
  end if;

  -- Determine if the invoice is currently a draft
  if old.status = 'draft' then
    -- Rule 3: Creator can change customer/amount when in draft
    if new.customer != old.customer then
      if new.created_by != auth.uid() then
        raise exception 'Only the creator can change customer';
      end if;
    end if;
    if new.amount != old.amount then
      if new.created_by != auth.uid() then
        raise exception 'Only the creator can change amount';
      end if;
    end if;
    -- Allow status change from draft to sent
    if new.status = 'sent' then
      return new;
    end if;
    -- Other status changes from draft are not allowed per rules, but we only permit draft→sent here;
    -- any other change will be caught by Rule 4 logic below.
    raise exception 'Invalid status change from draft';
  else
    -- Rule 4: Once not a draft, nobody can change customer or amount
    if new.customer != old.customer then
      raise exception 'Cannot change customer or amount on non-draft invoice';
    end if;
    if new.amount != old.amount then
      raise exception 'Cannot change customer or amount on non-draft invoice';
    end if;
    -- Rule 4: Finance staff can change status to paid or void; others cannot
    if old.status != new.status then
      if exists (select 1 from public.finance_staff where user_id = auth.uid()) then
        if new.status in ('paid', 'void') then
          return new;
        end if;
        raise exception 'Only finance staff can change status, and only to paid or void';
      else
        raise exception 'Only finance staff can change status';
      end if;
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger validate_invoice_update
  before update on public.invoices
  for each row
  execute function public.validate_invoice_update();

-- R5: Creators can delete their own draft invoices; no other invoice can be deleted
create policy "Creators can delete own draft invoices" on public.invoices
  for delete using (created_by = auth.uid() and old.status = 'draft');

-- R7: Users can see whether they themselves are finance staff; nobody can change finance_staff through the app
-- Grant select permission to authenticated users on finance_staff (they can check their own status)
grant select on public.finance_staff to authenticated;

-- Revoke all DML on finance_staff to prevent changes through the app
revoke all on public.finance_staff from public;
revoke all on public.finance_staff from authenticated;

-- R9: Server-side code using service role keeps full access (implicitly via service_role bypass)
-- No additional policy needed; service_role bypasses RLS.
