  select exists (
    select 1 from public.org_members
    where org_id = is_org_admin.org_id
    and user_id = auth.uid()
    and role = 'admin'
  );
$$;

-- R1: Members can see their organizations and every member of those organizations
create policy "Members can see orgs and members" on public.orgs
  for select using (auth.role() = 'authenticated');

create policy "Members can see org members" on public.org_members
  for select using (auth.role() = 'authenticated');

-- R2: Only admins can manage invites for their org; nobody can read invites without a token
create policy "Admins can manage invites" on public.invites
  for all using (
    auth.role() = 'authenticated' 
    and exists (
      select 1 from public.org_members
      where org_id = invites.org_id
      and user_id = auth.uid()
      and role = 'admin'
    )
  );

-- R5: Anonymous visitors cannot see or change anything (enforced by denying anon)
-- Explicitly deny anon access where needed
revoke all on public.orgs from anon;
revoke all on public.org_members from anon;
revoke all on public.invites from anon;

-- R6: Server-side code using the service role keeps full access (handled by Supabase auth, no additional grant needed)

-- R3: accept_invite RPC function
create function public.accept_invite(p_token text) returns bigint language sql strict as $$
declare
  v_org_id bigint;
  v_invited_by uuid;
  v_invitee_email text;
  v_invitee_lower text;
  v_inviter_email text;
  v_inviter_lower text;
begin
  -- Check if user is signed in
  if auth.uid() is null then
    raise exception 'User not signed in';
  end if;

  -- Find the invite by token
  select org_id, email, invited_by, expires_at, accepted_at
  into v_org_id, v_invitee_email, v_inviter_email, expires_at, accepted_at
  from public.invites
  where token = p_token;

  if not found then
    raise exception 'Unknown token';
  end if;

  -- Check if already accepted
  if accepted_at is not null then
    raise exception 'Invite already accepted';
  end if;

  -- Check if expired
  if expires_at < now() then
    raise exception 'Invite expired';
  end if;

  -- Check email match (case-insensitive, ignoring user_metadata)
  -- Supabase puts verified email in JWT claim `email`
  v_invitee_lower := lower(v_invitee_email);
  v_inviter_lower := lower(v_inviter_email);

  -- Get current user's verified email from JWT
  -- We compare the invite's email against the user's verified email
  -- Since we can't directly access auth.users verified email from RLS,
  -- we use the JWT claim `email` which Supabase provides
  -- We'll check by comparing with the authenticated user's email claim
  -- Using a subquery to get the user's email from their profile/jwt
  select lower((auth.jwt()->>'email')) into v_invitee_lower;

  if v_invitee_lower is null then
    raise exception 'Could not retrieve user email';
  end if;

  -- Compare emails case-insensitively
  if lower(v_invitee_email) != lower((auth.jwt()->>'email')) then
    raise exception 'Invite email does not match verified email';
  end if;

  -- Add user to org_members with the invite's role
  insert into public.org_members (org_id, user_id, role)
  values (v_org_id, auth.uid(), (select role from public.invites where token = p_token));

  -- Mark invite as accepted
  update public.invites
  set accepted_at = now()
  where token = p_token;

  return v_org_id;
end;
$$;

-- Grant execute on the function to authenticated users
grant execute on function public.accept_invite(text) to authenticated;
