```sql
-- Enable Row Level Security on all relevant tables
alter table public.projects enable row level security;
alter table public.project_members enable row level security;
alter table public.issues enable row level security;

-- Helper function: check if user is a maintainer of a given project
create function public.is_maintainer(project_id bigint, user_id uuid)
returns boolean language sql security invoker as $$
  select exists (
    select 1 from public.project_members
    where project_id = is_maintainer.project_id
    and user_id = is_maintainer.user_id
    and role = 'maintainer'
  );
$$;

-- Helper function: check if user is a reporter or maintainer of a given project
create function public.is_reporter_or_maintainer(project_id bigint, user_id uuid)
returns boolean language sql security invoker as $$
  select exists (
    select 1 from public.project_members
    where project_id = is_reporter_or_maintainer.project_id
    and user_id = is_reporter_or_maintainer.user_id
    and role in ('reporter', 'developer', 'maintainer')
  );
$$;

-- Helper function: check if user can see a specific issue
create function public.can_see_issue(issue_id bigint, user_id uuid)
returns boolean language sql security invoker as $$
declare
  issue_row public.issues%rowtype;
  project_maintainer boolean;
  is_assignee boolean;
begin
  select * into issue_row from public.issues where id = can_see_issue.issue_id;
  if not found then
    return false;
  end if;

  -- Must be a member of the project
  if not exists (
    select 1 from public.project_members
    where project_id = issue_row.project_id
    and user_id = can_see_issue.user_id
  ) then
    return false;
  end if;

  -- Confidential issues: only maintainers, reporter, or assignee
  if issue_row.is_confidential then
    project_maintainer := is_maintainer(issue_row.project_id, can_see_issue.user_id);
    is_assignee := issue_row.assignee_id = can_see_issue.user_id;
    return project_maintainer or issue_row.reporter_id = can_see_issue.user_id or is_assignee;
  end if;

  -- Non-confidential: any member can see
  return true;
end;
$$;

-- Helper function: check if user can update a specific issue
create function public.can_update_issue(issue_id bigint, user_id uuid)
returns boolean language sql security invoker as $$
declare
  issue_row public.issues%rowtype;
  is_maintainer boolean;
  is_reporter boolean;
  is_assignee boolean;
begin
  select * into issue_row from public.issues where id = can_update_issue.issue_id;
  if not found then
    return false;
  end if;

  -- Must be a member of the project
  if not exists (
    select 1 from public.project_members
    where project_id = issue_row.project_id
    and user_id = can_update_issue.user_id
  ) then
    return false;
  end if;

  is_maintainer := is_maintainer(issue_row.project_id, can_update_issue.user_id);
  is_reporter := issue_row.reporter_id = can_update_issue.user_id;
  is_assignee := issue_row.assignee_id = can_update_issue.user_id;

  -- Maintainers can do anything
  if is_maintainer then
    return true;
  end if;

  -- Assignees can update, but only non-confidential fields (enforced by policy)
  if is_assignee and not issue_row.is_confidential then
    return true;
  end if;

  -- Reporters and other members cannot update
  return false;
end;
$$;

-- Projects: members can see their projects and every member of those projects
create policy "project_members_view" on public.projects
for select using (
  exists (
    select 1 from public.project_members
    where project_id = id
    and user_id = auth.uid()
  )
);

-- Project members: members can see project members of their projects
create policy "project_members_select" on public.project_members
for select using (
  exists (
    select 1 from public.project_members pm2
    where pm2.project_id = project_members.project_id
    and pm2.user_id = auth.uid()
  )
);

-- Issues: members can see every non-confidential issue in their projects
create policy "issues_select_non_confidential" on public.issues
for select using (
  (not is_confidential) 
  and exists (
    select 1 from public.project_members
    where project_id = project_id
    and user_id = auth.uid()
  )
);

-- Issues: confidential issues visible only to maintainers, reporter, and assignee
create policy "issues_select_confidential" on public.issues
for select using (
  is_confidential 
  and can_see_issue(id, auth.uid())
);

-- Issues: allow inserting issues (R3)
create policy "issues_insert" on public.issues
for insert with check (
  project_id in (
    select project_id from public.project_members
    where user_id = auth.uid()
  )
  and status = 'open'
  and reporter_id = auth.uid()
);

-- Issues: update permissions (R4)
create policy "issues_update_maintainer" on public.issues
for update using can_update_issue(id, auth.uid());

-- Issues: prevent deletion (R5)
create policy "issues_delete_protected" on public.issues
for delete using (false);

-- Grants: allow authenticated users to use the helper functions
grant usage on schema public to authenticated;
grant execute on function public.is_maintainer(bigint, uuid) to authenticated;
grant execute on function public.is_reporter_or_maintainer(bigint, uuid) to authenticated;
grant execute on function public.can_see_issue(bigint, uuid) to authenticated;
grant execute on function public.can_update_issue(bigint, uuid) to authenticated;

-- Service role retains full access (no additional grants needed, RLS bypassed by service_role)
