  issue_row public.issues%rowtype;
  proj_id bigint;
  is_mem boolean;
  is_rep boolean;
  is_asg boolean;
  is_maint boolean;
begin
  select * into issue_row from public.issues where id = issue_id;
  if not found then return false; end if;

  proj_id := issue_row.project_id;

  -- Project membership check
  select exists(select 1 from public.project_members where project_id = proj_id and user_id = user_id) into is_mem;
  if not is_mem then return false; end if;

  -- Reporter or maintainer check for confidentiality
  select exists(select 1 from public.project_members where project_id = proj_id and user_id = user_id and role in ('reporter', 'developer', 'maintainer')) into is_rep;
  if not is_rep then return false; end if;

  -- Maintainer bypass for confidentiality
  select is_maintainer(proj_id, user_id) into is_maint;
  if is_maint then return true; end if;

  -- Assignee check
  select exists(select 1 from public.issues where id = issue_id and assignee_id = user_id) into is_asg;
  if is_asg then
    return not issue_row.is_confidential;
  end if;

  -- Reporter check
  if issue_row.reporter_id = user_id then
    return not issue_row.is_confidential;
  end if;

  -- Default: only non-confidential visible to others
  return not issue_row.is_confidential;
end;
$$;

