-- Enable RLS on all relevant tables
alter table public.pharmacists enable row level security;
alter table public.prescriptions enable row level security;
alter table public.dispenses enable row level security;

-- R1: Signed-in users can see pharmacists; patients see own prescriptions/dispenses; pharmacists see all
create policy "pharmacists_select_policy" on public.pharmacists
  for select using (auth.role() = 'authenticated');

create policy "patients_own_prescriptions_policy" on public.prescriptions
  for select using (
    auth.role() = 'authenticated' and
    patient_id = auth.uid()
  );

create policy "pharmacists_all_prescriptions_policy" on public.prescriptions
  for select using (auth.role() = 'authenticated');

create policy "patients_own_dispenses_policy" on public.dispenses
  for select using (
    auth.role() = 'authenticated' and
    prescription_id in (
      select id from public.prescriptions where patient_id = auth.uid()
    )
  );

create policy "pharmacists_all_dispenses_policy" on public.dispenses
  for select using (auth.role() = 'authenticated');

-- R2: No direct CRUD on prescriptions or dispenses from the app
create policy "no_app_crud_prescriptions" on public.prescriptions
  for all using (false);

create policy "no_app_crud_dispenses" on public.dispenses
  for all using (false);

-- R3–R5: dispense RPC function
create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
as $$
declare
  v_pharmacist_id uuid;
  v_refills_left integer;
begin
  -- R5: Anonymous visitors cannot use the function
  if auth.role() = 'anon' then
    raise exception 'Anonymous access not allowed';
  end if;

  -- R6: Service role keeps full access (security definer bypasses RLS)
  -- Validate caller is a pharmacist
  select user_id into v_pharmacist_id
  from public.pharmacists
  where user_id = auth.uid();

  if v_pharmacist_id is null then
    raise exception 'Caller is not a pharmacist';
  end if;

  -- Validate prescription exists and is not the caller's own (R4)
  if exists (
    select 1 from public.prescriptions
    where id = p_prescription_id
      and patient_id = auth.uid()
  ) then
    raise exception 'Cannot dispense your own prescription';
  end if;

  -- Validate prescription exists
  if not exists (select 1 from public.prescriptions where id = p_prescription_id) then
    raise exception 'Prescription does not exist';
  end if;

  -- Validate not expired and has refills left
  update public.prescriptions
  set refills_left = refills_left - 1
  where id = p_prescription_id
    and refills_left > 0
    and expires_at > now()
  returning refills_left into v_refills_left;

  if not found then
    -- R3/R4: raise error and change nothing when expired or no refills
    raise exception 'Prescription has expired or no refills left';
  end if;

  -- Record the dispense
  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, auth.uid(), now());

  return v_refills_left;
end;
$$;

-- R6: Grant service_role full access (already implied but explicit for clarity)
grant all on public.pharmacists to service_role;
grant all on public.prescriptions to service_role;
grant all on public.dispenses to service_role;

-- Grant usage of the function to authenticated users (R1)
grant execute on public.dispense to authenticated;
