alter table public.pharmacists enable row level security;
alter table public.prescriptions enable row level security;
alter table public.dispenses enable row level security;

-- Create helper function to check if current user is a pharmacist
create or replace function public.is_pharmacist()
returns boolean language sql secure as $$
  select exists (
    select 1 from public.pharmacists
    where user_id = auth.uid()
  );
$$;

-- Create helper function to get the pharmacist id for the current user
create or replace function public.get_pharmacist_id()
returns uuid language sql secure as $$
  select user_id from public.pharmacists
  where user_id = auth.uid();
$$;

-- POLICY: R1 - Signed-in users can see who the pharmacists are
create policy "Pharmacists are visible to signed-in users"
on public.pharmacists for select
using (auth.role() = 'authenticated');

-- POLICY: R1 - Patients can see their own prescriptions
create policy "Patients can see own prescriptions"
on public.prescriptions for select
using (
  auth.role() = 'authenticated'
  and patient_id = auth.uid()
);

-- POLICY: R1 - Pharmacists can see every prescription and every dispense
create policy "Pharmacists can see all prescriptions and dispenses"
on public.prescriptions for select
using (public.is_pharmacist());

create policy "Pharmacists can see all dispenses"
on public.dispenses for select
using (public.is_pharmacist());

-- POLICY: R2 - Nobody can create, change or delete prescriptions or dispenses directly
-- (Insert, update, delete are all restricted; only service_role via RPC has access)

-- POLICY: R5 - Anonymous visitors cannot see or change anything
-- The select policies above already restrict to auth.role() = 'authenticated', 
-- but we explicitly deny anon access to be safe
create policy "Anonymous access denied"
on public.pharmacists for select, insert, update, delete
using (false);

create policy "Anonymous access denied"
on public.prescriptions for select, insert, update, delete
using (false);

create policy "Anonymous access denied"
on public.dispenses for select, insert, update, delete
using (false);

-- Create the dispense function (R3, R4)
create or replace function public.dispense(p_prescription_id bigint)
returns integer language plpgsql security definer as $$
declare
  v_pharmacist_id uuid;
  v_patient_id uuid;
  v_refills_left integer;
  v_expires_at timestamptz;
  v_caller_is_patient boolean;
begin
  -- Check that the caller is a pharmacist (R4)
  select user_id into v_pharmacist_id
  from public.pharmacists
  where user_id = auth.uid();

  if v_pharmacist_id is null then
    raise exception 'Caller is not a pharmacist';
  end if;

  -- Check prescription exists (R4)
  select patient_id, refills_left, expires_at into v_patient_id, v_refills_left, v_expires_at
  from public.prescriptions
  where id = p_prescription_id;

  if not found then
    raise exception 'Prescription does not exist';
  end if;

  -- Check expiry (R4)
  if v_expires_at < now() then
    raise exception 'Prescription has expired';
  end if;

  -- Check refills left (R4)
  if v_refills_left <= 0 then
    raise exception 'No refills left';
  end if;

  -- Check that the prescription is not the caller's own (R4)
  -- We need to determine if the caller is the patient of this prescription
  -- Since we don't have a direct way to know the caller's identity beyond auth.uid(),
  -- and the caller is a pharmacist, we check if the pharmacist user_id matches the patient_id
  -- This scenario is unlikely but per rules we must handle it.
  -- Note: pharmacists and patients are different users, but we check anyway.
  if v_patient_id = auth.uid() then
    raise exception 'Prescription is the caller\'s own';
  end if;

  -- Decrement refills left (R3)
  update public.prescriptions
  set refills_left = refills_left - 1
  where id = p_prescription_id;

  -- Record the dispense (R3)
  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, v_pharmacist_id, now());

  -- Return the refills left afterwards
  return (v_refills_left - 1);
end;
$$;

-- Grant permissions to authenticated users for the functions
grant usage on function public.is_pharmacist() to authenticated;
grant usage on function public.get_pharmacist_id() to authenticated;
grant execute on function public.dispense() to authenticated;

-- Grant service_role full access (R6)
grant all on public.pharmacists to service_role;
grant all on public.prescriptions to service_role;
grant all on public.dispenses to service_role;

