-- Enable Row Level Security on all relevant tables
alter table public.pharmacists enable row level security;
alter table public.prescriptions enable row level security;
alter table public.dispenses enable row level security;

-- Create helper function to check if current user is a pharmacist
create or replace function public.is_pharmacist()
returns boolean language sql secure as $$
  select exists (
    select 1 from public.pharmacists
    where user_id = auth.uid()
  );
$$;

-- Create helper function to get the pharmacist id for the current user
create or replace function public.get_pharmacist_id()
returns uuid language sql secure as $$
  select user_id from public.pharmacists
  where user_id = auth.uid();
$$;

-- POLICY: R1 - Signed-in users can see who the pharmacists are
create policy "Pharmacists are visible to signed-in users"
on public.pharmacists for select
using (auth.role() = 'authenticated');

-- POLICY: R1 - Patients can see their own prescriptions
create policy "Patients can see own prescriptions"
on public.prescriptions for select
using (
  auth.role() = 'authenticated'
  and patient_id = auth.uid()
);

-- POLICY: R1 - Pharmacists can see every prescription and every dispense
create policy "Pharmacists can see all prescriptions and dispenses"
on public.prescriptions for select
using (public.is_pharmacist());

create policy "Pharmacists can see all dispenses"
on public.dispenses for select
using (public.is_pharmacist());

-- POLICY: R2 - Nobody can create, change or delete prescriptions or dispenses directly through the app
create policy "No direct insert on prescriptions"
on public.prescriptions for insert
with check (false);

create policy "No direct update on prescriptions"
on public.prescriptions for update
using (false);

create policy "No direct delete on prescriptions"
on public.prescriptions for delete
using (false);

create policy "No direct insert on dispenses"
on public.dispenses for insert
with check (false);

create policy "No direct update on dispenses"
on public.dispenses for update
using (false);

create policy "No direct delete on dispenses"
on public.dispenses for delete
using (false);

-- POLICY: R3 & R4 - The dispense function
-- R3: dispense takes one refill off the prescription and records a dispense by the calling pharmacist
-- R4: dispense must raise an error and change nothing when the caller is not a pharmacist, the prescription does not exist, has expired or has no refills left, or the prescription is the caller's own
create or replace function public.dispense(p_prescription_id bigint)
returns integer language plpgsql security definer as $$
declare
  v_pharmacist_id uuid;
  v_patient_id uuid;
  v_refills integer;
  v_expires_at timestamptz;
  v_current_user uuid;
begin
  -- Get the current user's id
  v_current_user := auth.uid();

  -- Check if the caller is a pharmacist
  if not public.is_pharmacist() then
    raise exception 'Only pharmacists can dispense medications';
  end if;

  v_pharmacist_id := public.get_pharmacist_id();

  -- Check if the prescription exists
  if not exists (select 1 from public.prescriptions where id = p_prescription_id) then
    raise exception 'Prescription does not exist';
  end if;

  -- Get prescription details into variables
  select patient_id, refills_left, expires_at
  into v_patient_id, v_refills, v_expires_at
  from public.prescriptions
  where id = p_prescription_id;

  -- Check if the prescription has expired
  if v_expires_at < now() then
    raise exception 'Prescription has expired';
  end if;

  -- Check if the prescription has no refills left
  if v_refills <= 0 then
    raise exception 'No refills left on this prescription';
  end if;

  -- Check if the prescription is the caller's own (pharmacist cannot dispense their own prescriptions)
  if v_patient_id = v_current_user then
    raise exception 'Pharmacists cannot dispense their own prescriptions';
  end if;

  -- Decrement the refills left
  update public.prescriptions
  set refills_left = refills_left - 1
  where id = p_prescription_id;

  -- Record the dispense
  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, v_pharmacist_id, now());

  -- Return the refills left after dispensing
  return (select refills_left from public.prescriptions where id = p_prescription_id);
end;
$$;

-- Grant usage on the function to authenticated users
grant execute on public.dispense to authenticated;

-- Grant usage on the helper functions
grant execute on public.is_pharmacist to authenticated;
grant execute on public.get_pharmacist_id to authenticated;

-- Grant all permissions to service_role (bypasses RLS)
grant all on public.pharmacists to service_role;
grant all on public.prescriptions to service_role;
grant all on public.dispenses to service_role;

-- Revoke public access (ensure anon cannot access)
revoke all on public.pharmacists from public;
revoke all on public.prescriptions from public;
revoke all on public.dispenses from public;
```

