-- Enable Row Level Security
alter table public.pharmacists enable row level security;
alter table public.prescriptions enable row level security;
alter table public.dispenses enable row level security;

-- Helper function to check if current user is a pharmacist
create or replace function public.is_pharmacist() returns boolean language plpgsql as $$
begin
  return exists(select 1 from public.pharmacists where user_id = auth.uid());
end;
$$;

-- R1: Signed-in users can see pharmacists
create policy "pharmacists_select_policy" on public.pharmacists
for select using (auth.role() = 'authenticated');

-- R1: Patients can see their own prescriptions, pharmacists can see all
create policy "prescriptions_select_policy" on public.prescriptions
for select using (
  auth.role() = 'authenticated' and (
    patient_id = auth.uid() 
    or exists(select 1 from public.pharmacists where user_id = auth.uid())
  )
);

-- R1: Pharmacists can see all dispenses, patients can see dispenses of their own prescriptions
create policy "dispenses_select_policy" on public.dispenses
for select using (
  auth.role() = 'authenticated' and (
    exists(select 1 from public.prescriptions where id = prescription_id and patient_id = auth.uid())
    or exists(select 1 from public.pharmacists where user_id = auth.uid())
  )
);

-- R2: Block all direct DML on prescriptions and dispenses
create policy "prescriptions_no_dml" on public.prescriptions
for all using (false);

create policy "dispenses_no_dml" on public.dispenses
for all using (false);

-- R3, R4, R6: dispense RPC function
create or replace function public.dispense(p_prescription_id bigint) returns integer language plpgsql as $$
declare
  v_pharmacist_id uuid;
  v_patient_id uuid;
  v_refills_left integer;
  v_expires_at timestamptz;
  v_dispensed_at timestamptz;
begin
  -- R6: Service role bypasses RLS checks below (but we still validate logically)
  if auth.role() = 'service_role' then
    -- Service role: just perform the operation
    update public.prescriptions
    set refills_left = refills_left - 1
    where id = p_prescription_id
      and refills_left > 0
      and expires_at > now();

    if not found then
      signal sqlstate '45000' set message_text = 'Prescription not found, expired, or no refills left';
    end if;

    insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
    values (p_prescription_id, auth.uid(), now());

    return (select refills_left from public.prescriptions where id = p_prescription_id);
  end if;

  -- R3/R4: Regular authenticated user checks
  -- R4: Caller must be a pharmacist
  if not public.is_pharmacist() then
    signal sqlstate '45000' set message_text = 'Caller is not a pharmacist';
  end if;

  -- R4: Prescription must exist
  select patient_id, refills_left, expires_at into v_patient_id, v_refills_left, v_expires_at
  from public.prescriptions
  where id = p_prescription_id;

  if not found then
    signal sqlstate '45000' set message_text = 'Prescription does not exist';
  end if;

  -- R4: Prescription must not be expired
  if v_expires_at <= now() then
    signal sqlstate '45000' set message_text = 'Prescription has expired';
  end if;

  -- R4: Prescription must have refills left
  if v_refills_left <= 0 then
    signal sqlstate '45000' set message_text = 'Prescription has no refills left';
  end if;

  -- R4: Prescription must not be the caller's own
  if v_patient_id = auth.uid() then
    signal sqlstate '45000' set message_text = 'Prescription is the caller''s own';
  end if;

  -- Perform the dispense
  update public.prescriptions
  set refills_left = refills_left - 1
  where id = p_prescription_id;

  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, auth.uid(), now());

  return (select refills_left from public.prescriptions where id = p_prescription_id);
end;
$$;

-- R5: Anonymous access denied (default deny via RLS)
-- No additional policies needed; RLS enabled above with select policies requiring auth.role() = 'authenticated' blocks anon.

-- Grants for service role (R6)
grant all on public.pharmacists to service_role;
grant all on public.prescriptions to service_role;
grant all on public.dispenses to service_role;

-- Grants for authenticated users (R1)
grant select on public.pharmacists to authenticated;
grant select on public.prescriptions to authenticated;
grant select on public.dispenses to authenticated;
