-- Enable RLS on the public.pastes table
alter table public.pastes enable row level security;

-- RLS Policy: Read access for anyone (anonymous or signed-in) for non-private, non-expired pastes
create policy "R1_Read_public_pastes" on public.pastes
for select using (
  is_private = false 
  and (expires_at is null or expires_at > now())
);

-- RLS Policy: Authors can read their own private and expired pastes (R2)
create policy "R2_Authors_read_own" on public.pastes
for select using (
  auth.role() = 'authenticated' 
  and author_id = auth.uid()
);

-- RLS Policy: Anyone can create pastes, anonymous pastes cannot be private (R3)
create policy "R3_Create_paste" on public.pastes
for insert with check (
  -- Anonymous users (author_id is null/empty) cannot set is_private to true
  (author_id is null or auth.role() = 'authenticated' or is_private = false)
);

-- RLS Policy: Authors can delete their own pastes (R4)
create policy "R4_Authors_delete_own" on public.pastes
for delete using (
  auth.role() = 'authenticated' 
  and author_id = auth.uid()
);

-- RLS Policy: No updates allowed (edit protection)
create policy "No_updates_allowed" on public.pastes
for update with check (false);

-- RLS Policy: Anonymous pastes (author_id is null) can only be removed by service_role
create policy "Anonymous_pastes_service_only" on public.pastes
for delete using (
  auth.role() != 'service_role' 
  and author_id is not null
);

-- Grant public select on pastes for anonymous access (supports R1)
grant select on public.pastes to anon, authenticated;

-- Revoke unnecessary permissions to enforce RLS rules
revoke delete, update, insert on public.pastes from anon, authenticated;
