-- Enable RLS on all relevant tables
alter table public.projects enable row level security;
alter table public.translators enable row level security;
alter table public.segments enable row level security;

-- Helper function to check if user is assigned to a project as translator or reviewer for a given language
create function public.is_assigned_to_project(p_project_id bigint, p_lang text, p_user_id uuid)
returns boolean language sql security invoker
as $$
  select exists (
    select 1 from public.translators
    where project_id = p_project_id
      and lang = p_lang
      and user_id = p_user_id
      and role in ('translator', 'reviewer')
  );
$$;

-- Helper function to check if user is a reviewer for a project/language
create function public.is_reviewer_of_project(p_project_id bigint, p_lang text, p_user_id uuid)
returns boolean language sql security invoker
as $$
  select exists (
    select 1 from public.translators
    where project_id = p_project_id
      and lang = p_lang
      and user_id = p_user_id
      and role = 'reviewer'
  );
$$;

-- Helper function to check if segment is in draft status
create function public.is_draft_segment(p_segment_id bigint)
returns boolean language sql security invoker
as $$
  select exists (
    select 1 from public.segments
    where id = p_segment_id
      and status = 'draft'
  );
$$;

-- Projects RLS: Users can see projects they are assigned to
create policy "Users can see projects they work on" on public.projects
for select using (
  exists (
    select 1 from public.translators
    where project_id = id
      and user_id = auth.uid()
  )
);

-- Translators RLS: Users can see their assignment rows
create policy "Users can see own assignment rows" on public.translators
for select using (user_id = auth.uid());

-- Segments RLS

-- R1: Users can see segments of languages they are assigned to
create policy "Users can see segments of assigned languages" on public.segments
for select using (
  is_assigned_to_project(project_id, lang, auth.uid())
);

-- R2: Translators can edit draft segments in their language, recording themselves
create policy "Translators can edit draft segments in their language" on public.segments
for update using (
  is_draft_segment(id) 
  and is_assigned_to_project(project_id, lang, auth.uid())
  and not is_reviewer_of_project(project_id, lang, auth.uid()) -- translators only, not reviewers
)
with check (
  -- Always record the translator in translated_by
  (translated_by = auth.uid() or translated_by is null)
  and status = 'draft'
);

-- R3: Reviewers can mark draft segments reviewed (and may correct translation)
create policy "Reviewers can mark segments reviewed and correct translation" on public.segments
for update using (
  is_draft_segment(id)
  and is_reviewer_of_project(project_id, lang, auth.uid())
)
with check (
  -- Reviewers can set status to reviewed and may update target_text/translated_by
  (status = 'reviewed' or target_text is not null)
  and translated_by = auth.uid() -- reviewers can also record themselves if needed, or leave as is
);

-- R4: Reviewed segments can no longer be changed
-- Prevent updates on reviewed segments (except by service_role which bypasses RLS)
-- We enforce this at the application level via checks, but RLS prevents updates on reviewed segments for non-service roles
-- The update policies above already restrict to draft segments, so reviewed segments are implicitly protected.

-- R5: Anonymous visitors cannot see or change anything
-- anon role has no policies, so they get permission denied by default.

-- R6: Server-side code using service role keeps full access
-- service_role bypasses RLS by default, no additional policy needed.

-- Grants: Ensure authenticated users can use the helper functions (optional, but good practice)
grant usage on schema public to authenticated;
grant execute on function public.is_assigned_to_project(bigint, text, uuid) to authenticated;
grant execute on function public.is_reviewer_of_project(bigint, text, uuid) to authenticated;
grant execute on function public.is_draft_segment(bigint) to authenticated;

-- Revoke anon access to tables (already protected by lack of policies, but explicit)
revoke all on public.projects from anon;
revoke all on public.translators from anon;
revoke all on public.segments from anon;
