-- Enable Row Level Security on both tables
alter table public.envelopes enable row level security;
alter table public.envelope_recipients enable row level security;

-- Helper function to check if all recipients have signed
create or replace function public.check_all_signed(p_envelope_id bigint) returns boolean language sql immutable as $$
  select count(*) = 0
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and signed_at is null;
$$;

-- Policy: Senders and recipients can view envelopes and recipient lists
create policy "senders_and_recipients_view" on public.envelopes
  for select using (
    auth.uid() = sender_id
    or exists (
      select 1 from public.envelope_recipients
      where envelope_id = id and user_id = auth.uid()
    )
  );

create policy "senders_and_recipients_view_recipients" on public.envelope_recipients
  for select using (
    exists (
      select 1 from public.envelopes
      where id = envelope_id
        and (sender_id = auth.uid()
          or exists (
            select 1 from public.envelope_recipients r2
            where r2.envelope_id = id and r2.user_id = auth.uid()
          ))
    )
  );

-- Policy: Prevent direct DML on envelopes and recipients (R2)
create policy "no_dml_envelopes" on public.envelopes
  for all using (false);

create policy "no_dml_recipients" on public.envelope_recipients
  for all using (false);

-- R3: sign_envelope RPC
create or replace function public.sign_envelope(p_envelope_id bigint) returns text language plpgsql security definer as $$
declare
  v_sender_id uuid;
  v_status text;
  v_already_signed boolean;
  v_earlier_signed boolean;
  v_all_signed boolean;
begin
  -- Ensure caller is a recipient of this envelope
  if not exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id and user_id = auth.uid()
  ) then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  -- Check envelope status
  select status, sender_id into v_status, v_sender_id
  from public.envelopes
  where id = p_envelope_id;

  if v_status != 'sent' then
    raise exception 'Envelope is not in ''sent'' status';
  end if;

  -- Check if caller already signed
  select exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id and user_id = auth.uid() and signed_at is not null
  ) into v_already_signed;

  if v_already_signed then
    raise exception 'Caller has already signed this envelope';
  end if;

  -- Check if any earlier sign_order has not signed yet
  select exists (
    select 1 from public.envelope_recipients r2
    where r2.envelope_id = p_envelope_id
      and r2.sign_order < (
        select sign_order from public.envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid()
      )
      and r2.signed_at is null
  ) into v_earlier_signed;

  if v_earlier_signed then
    raise exception 'An earlier recipient in sign_order has not signed yet';
  end if;

  -- Record the signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = auth.uid();

  -- Check if all recipients now signed
  select public.check_all_signed(p_envelope_id) into v_all_signed;

  if v_all_signed then
    update public.envelopes set status = 'completed' where id = p_envelope_id;
  end if;

  return (select status from public.envelopes where id = p_envelope_id);
end;
$$;

-- R4: void_envelope RPC
create or replace function public.void_envelope(p_envelope_id bigint) returns text language plpgsql security definer as
$$
declare
  v_status text;
  v_sender_id uuid;
begin
  -- Ensure caller is the sender
  select status, sender_id into v_status, v_sender_id
  from public.envelopes
  where id = p_envelope_id;

  if auth.uid() != v_sender_id then
    raise exception 'Only the sender can void this envelope';
  end if;

  if v_status != 'sent' then
    raise exception 'Envelope is not in ''sent'' status and cannot be voided';
  end if;

  update public.envelopes set status = 'voided' where id = p_envelope_id;

  return (select status from public.envelopes where id = p_envelope_id);
end;
$$;

-- R5: Anonymous visitors cannot see or change anything is implicitly handled
-- because policies reference auth.uid() and anon role has no access.

-- R6: Server-side code using service_role keeps full access is handled
-- by the service_role bypassing RLS by default.

-- Grant usage on schemas and functions to authenticated users where needed
grant usage on schema public to authenticated;
grant execute on function public.sign_envelope(bigint) to authenticated;
grant execute on function public.void_envelope(bigint) to authenticated;
