-- This is enforced by a trigger that resets sent_at to null if attempted update
create or replace function prevent_sent_at_change()
returns trigger as $$
begin
  -- If sent_at is being set or changed by a non-service role user, reject
  if new.sent_at is distinct from coalesce(old.sent_at, '') then
    if current_setting('role') != 'service_role' then
      signal sqlstate '45000' using message = 'Cannot modify sent_at; email is already sent or being sent.';
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

