  using ( visibility = 'public' );

-- R2: Signed-in users can read profiles with visibility = 'members'
create policy "Members profiles are readable by signed-in users"
  on public.profiles
  for select
  using ( visibility = 'members' and auth.role() = 'authenticated' );

-- R3: Users can create, update, and delete only their own profile
-- Create function to validate ownership (optional helper, but good practice)
create or replace function public.validate_profile_ownership()
returns trigger as $$
begin
  -- Ensure user_id always matches the authenticated user performing the action
  if (TG_OP = 'DELETE') then
    if (old.user_id <> auth.uid()) then
      signal sqlstate '45000' set message_text = 'You can only delete your own profile';
    end if;
    return old;
  end if;

  if (TG_OP = 'UPDATE') then
    if (new.user_id <> auth.uid()) then
      signal sqlstate '45000' set message_text = 'You can only update your own profile';
    end if;
    -- Enforce that visibility cannot be changed to a different user's context
    -- (The user_id column itself is immutable via the constraint below)
    return new;
  end if;

  if (TG_OP = 'INSERT') then
    -- New profiles must have user_id set to the current authenticated user
    new.user_id := auth.uid();
    return new;
  end if;

  return null;
end;
$$ language plpgsql security definer;

-- Attach the ownership validation trigger
create trigger validate_profile_ownership
  before insert or update or delete on public.profiles
  for each row
  execute function public.validate_profile_ownership();

-- R4: Anonymous visitors cannot create or change profiles
-- This is implicitly handled by the trigger above (INSERT requires auth.uid())
-- and the fact that anon role cannot execute actions without proper policy.

-- R5: Service role bypasses RLS (already granted by Supabase default)
-- No additional grant needed; service_role bypasses RLS by default.

-- Explicit grants for clarity and robustness
-- Allow authenticated users to perform actions on their own profiles
grant select, insert, update, delete on public.profiles to authenticated;

-- Revoke public access that might conflict with RLS policies
