alter table public.hoa_admins enable row level security;
alter table public.permits enable row level security;

-- R1: Residents see their own residence and their unit's permits; HOA admins see all permits
create policy "residents_see_own_residence" on public.residents
  for select using (user_id = auth.uid());

create policy "residents_see_own_unit_permits" on public.permits
  for select using (
    exists (
      select 1 from public.residents r
      where r.unit_id = permits.unit_id
        and r.user_id = auth.uid()
    )
  );

create policy "hoa_admins_see_all_permits" on public.permits
  for select using (
    exists (
      select 1 from public.hoa_admins
      where user_id = auth.uid()
    )
  );

-- R2: Residents add permits for their unit (max 2 active permits per unit)
create function public.check_max_two_active_permits(unit_id bigint)
returns boolean
language plpgsql
security definer
as $$
begin
  return (
    select count(*) = 0
    from public.permits p
    where p.unit_id = check_max_two_active_permits.unit_id
      and p.revoked = false
      and p.valid_until >= current_date
  );
end;
$$;

create policy "residents_add_permit_max_two" on public.permits
  for insert with check (
    exists (
      select 1 from public.residents r
      where r.unit_id = unit_id
        and r.user_id = auth.uid()
    )
    and check_max_two_active_permits(unit_id)
  );

-- R3: Residents change plate on their unit's permits only, cannot change validity or revoke
create policy "residents_update_plate_only" on public.permits
  for update using (
    exists (
      select 1 from public.residents r
      where r.unit_id = permits.unit_id
        and r.user_id = auth.uid()
    )
  )
  with check (
    -- Only allow plate column to change, validity and revoked must stay the same
    plate = old.plate
    and valid_until = old.valid_until
    and revoked = old.revoked
  );

-- R4: HOA admins can revoke any permit; nobody can un-revoke
create policy "hoa_admins_revoke_permit" on public.permits
  for update using (
    exists (
      select 1 from public.hoa_admins
      where user_id = auth.uid()
    )
  )
  with check (
    revoked = true
  );

-- Prevent un-revoking: revoked can only go from false to true, never back to false
-- This is enforced by the with check clause above combined with the revoked default false.

-- R5: Anonymous visitors cannot see or change anything
-- No policies for anon; anon has no access by default.

-- R6: Server-side code using service role keeps full access
-- service_role bypasses RLS by default; no additional grant needed.

-- Grants: ensure authenticated users can use the app
grant usage on schema public to authenticated;
grant all on public.residents to authenticated;
grant all on public.hoa_admins to authenticated;
grant select, insert, update on public.permits to authenticated;

-- Revoke from anon (explicit, though anon has no access by default)
