  for select using (
    exists (
      select 1 from public.hoa_admins
      where hoa_admins.user_id = auth.uid()
    )
  );

-- R2: Insert policy for permits (Residents add permits)
create policy "Residents add permits for own unit" on public.permits
  for insert with check (
    exists (
      select 1 from public.residents
      where residents.unit_id = permits.unit_id
      and residents.user_id = auth.uid()
    )
    and (
      -- Count active permits for the unit (not revoked and valid_until >= current_date)
      (select count(*) from public.permits p2
       where p2.unit_id = permits.unit_id
       and p2.revoked = false
       and p2.valid_until >= current_date) < 2
    )
  );

-- R3: Update policy for permits (Residents change plate only)
create policy "Residents change plate on own permits" on public.permits
  for update using (
    exists (
      select 1 from public.residents
      where residents.unit_id = permits.unit_id
      and residents.user_id = auth.uid()
    )
  )
  with check (
    -- Only the plate column may change; validity and revoked must stay the same
    plate = old.plate
    and valid_until = old.valid_until
    and revoked = old.revoked
  );

-- R4: HOA admins revoke permits; nobody can un-revoke
create policy "HOA admins revoke permits" on public.permits
  for update using (
    exists (
      select 1 from public.hoa_admins
      where hoa_admins.user_id = auth.uid()
    )
  )
  with check (
    revoked = true
  );

-- Policy to prevent un-revoking (revoked can only go from false to true, never back to false)
-- This is enforced via the with check on the HOA admin policy above, plus an additional check on any update that attempts to set revoked=false on an already revoked permit.
-- We add a restrictive policy for non-admin users to ensure they cannot set revoked=false on a revoked permit.
create policy "Prevent un-revoking permits" on public.permits
  for update using (
    -- If the permit is already revoked, no one can set revoked=false
    (revoked = true and revoked = old.revoked) -- effectively blocks any update setting revoked=false on a revoked row
    or
    -- If not revoked, normal rules apply (residents can't change revoked status)
    (revoked = false and not exists (select 1 from public.hoa_admins where hoa_admins.user_id = auth.uid()))
  )
  with check (
    -- Allow HOA admins to set revoked=true; everyone else cannot change revoked
    (exists (select 1 from public.hoa_admins where hoa_admins.user_id = auth.uid()) and revoked = true)
    or
    (not exists (select 1 from public.hoa_admins where hoa_admins.user_id = auth.uid()) and revoked = false and revoked = old.revoked)
  );

-- R5: Anonymous and non-authorized users cannot change residents or HOA admins
-- No insert/update/delete policies on residents/hoa_admins beyond what is needed; we explicitly deny via revoke below.
-- Revoke all default policies to ensure anon/authenticated without role have no access
revoke all on public.residents from public;
revoke all on public.hoa_admins from public;
revoke all on public.permits from public;

-- R6: Service role keeps full access (granted implicitly by Supabase, but we ensure it via grant)
grant all on public.residents to service_role;
grant all on public.hoa_admins to service_role;
grant all on public.permits to service_role;

-- Grant authenticated users the roles they need (authenticated role gets select/insert/update per policies)
grant select, insert, update on public.permits to authenticated;
grant select on public.residents to authenticated;
grant usage on sequence public.permits_id_seq to authenticated;
