-- Enable RLS on all relevant tables
alter table public.residents enable row level security;
alter table public.hoa_admins enable row level security;
alter table public.permits enable row level security;

-- RLS Policies for residents table
-- Residents can see their own rows; nobody else can
create policy "Residents can view own rows" on public.residents
  for select using (auth.uid() = user_id);

-- HOA admins can view all resident rows
create policy "HOA admins can view all residents" on public.residents
  for select using (auth.role() = 'authenticated' and exists (select 1 from public.hoa_admins where user_id = auth.uid()));

-- Nobody can insert/update/resident rows through the app
create policy "No modifications to residents" on public.residents
  for all using (false);

-- RLS Policies for hoa_admins table
-- HOA admins can view the list; nobody else can
create policy "HOA admins can view admins" on public.hoa_admins
  for select using (auth.role() = 'authenticated' and exists (select 1 from public.hoa_admins where user_id = auth.uid()));

-- Nobody can modify hoa_admins through the app
create policy "No modifications to hoa_admins" on public.hoa_admins
  for all using (false);

-- Helper function to count active permits for a unit
create or replace function public.count_active_permits(unit_id bigint)
returns integer language sql stable security definer as $$
  select count(*) from public.permits
  where unit_id = count_active_permits.unit_id
    and not revoked
    and valid_until >= current_date;
$$;

-- RLS Policies for permits table

-- R1: Residents can see their own residence rows and the permits of their unit
create policy "Residents see own permits" on public.permits
  for select using (
    -- Residents can see permits for their own unit
    exists (select 1 from public.residents where unit_id = permits.unit_id and user_id = auth.uid())
    or
    -- HOA admins can see every permit
    auth.role() = 'authenticated' and exists (select 1 from public.hoa_admins where user_id = auth.uid())
  );

-- R2: Residents can add permits for their own unit while it has fewer than 2 active permits
create policy "Residents add permits" on public.permits
  for insert with check (
    -- Must be a resident of the unit
    exists (select 1 from public.residents where unit_id = unit_id and user_id = auth.uid())
    and
    -- Unit must have fewer than 2 active permits
    (count_active_permits(unit_id) < 2)
  );

-- R3: Residents can change the plate on their unit's permits, but cannot change validity or revoke
create policy "Residents update plate" on public.permits
  for update using (
    -- Must be a resident of the unit owning this permit
    exists (select 1 from public.residents where unit_id = permits.unit_id and user_id = auth.uid())
  )
  with check (
    -- Only the plate column may change; validity and revoked must stay the same
    plate is not null and
    valid_until = old.valid_until and
    revoked = old.revoked
  );

-- R4: HOA admins can revoke any permit; nobody can un-revoke. Permits are never deleted.
create policy "HOA admins revoke permits" on public.permits
  for update using (
    auth.role() = 'authenticated' and exists (select 1 from public.hoa_admins where user_id = auth.uid())
  )
  with check (
    -- Can only set revoked to true; cannot un-revoke
    revoked = true
  );

-- Prevent any deletes on permits
create policy "Prevent permit deletes" on public.permits
  for delete using (false);

-- R5: Anonymous visitors cannot see or change anything
-- The above policies already restrict to authenticated users; anon role has no access by default.

-- R6: Server-side code using the service role keeps full access
-- service_role bypasses RLS by default; no additional policy needed.
